//! Integration control only: arbitrary raw inputs, not a failure-rate gate.
#[path="../io.rs"]mod io;
use quantum_ecc::{circuit::{Op,OperationType as K},sim::Simulator};
use sha3::{Shake256,digest::{Update,ExtendableOutput,XofReader}};
const NO:u64=u64::MAX;
fn dims(v:&[Op])->(usize,usize){let q=v.iter().flat_map(|o|[o.q_control1.0,o.q_control2.0,o.q_target.0]).filter(|&q|q!=NO).max().unwrap_or(0)as usize+1;let b=v.iter().flat_map(|o|[o.c_condition.0,o.c_target.0]).filter(|&q|q!=NO).max().unwrap_or(0)as usize+1;(q,b)}
fn rng(label:&str,batch:u64)->impl XofReader{let mut h=Shake256::default();h.update(label.as_bytes());h.update(&batch.to_le_bytes());h.finalize_xof()}
fn word(r:&mut impl XofReader)->u64{let mut x=[0u8;8];r.read(&mut x);u64::from_le_bytes(x)}
fn run(v:&[Op],batch:u64,input:&[(bool,usize,u64)],phase:u64)->(Vec<u64>,Vec<u64>,u64,u64,Vec<u8>){let(nq,nb)=dims(v);let mut r=rng("order-control-physical-RNG-20261019",batch);let mut s=Simulator::new(nq,nb,&mut r);s.phase=phase;for &(q,i,value)in input{if q{s.qubits[i]=value}else{s.bits[i]=value}}s.apply_iter(v.iter());let state=(s.qubits.clone(),s.bits.clone(),s.phase,s.stats.toffoli_gates);drop(s);let mut tail=vec![0;64];r.read(&mut tail);(state.0,state.1,state.2,state.3,tail)}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),5);let original=io::load_ops(&a[1]);let reordered=io::load_ops(&a[2]);let colored=io::load_ops(&a[3]);let registered:std::collections::BTreeSet<_>=original.iter().filter(|o|o.kind==K::AppendToRegister&&o.q_target.0!=NO).map(|o|o.q_target.0 as usize).collect();let mut rows=vec![];
 for batch in 0..8{let mut r=rng("order-control-uniform-raw-inputs-20261019",batch);let mut input=vec![];let mut seen=std::collections::BTreeSet::new();for o in &original{if o.kind==K::AppendToRegister{for(q,i)in [(true,o.q_target.0),(false,o.c_target.0)]{if i!=NO&&seen.insert((q,i)){input.push((q,i as usize,word(&mut r)));}}}}let phase=word(&mut r);let x=run(&original,batch,&input,phase);let y=run(&reordered,batch,&input,phase);assert_eq!(x,y,"complete reordered transcript differs at batch{batch}");let z=run(&colored,batch,&input,phase);assert_eq!(x.1,z.1,"classical bits");assert_eq!(x.2,z.2,"phase");assert_eq!(x.3,z.3,"executed Toffolis");assert_eq!(x.4,z.4,"physical RNG continuation");for &q in &registered{assert_eq!(x.0[q],z.0[q],"registered output {q}");}let mut xx:Vec<_>=x.0.iter().enumerate().filter(|(q,_)|!registered.contains(q)).map(|(_,x)|*x).collect();let mut zz:Vec<_>=z.0.iter().enumerate().filter(|(q,_)|!registered.contains(q)).map(|(_,x)|*x).collect();let width=xx.len().max(zz.len());xx.resize(width,0);zz.resize(width,0);xx.sort_unstable();zz.sort_unstable();assert_eq!(xx,zz,"scratch state multiset");rows.push(serde_json::json!({"batch":batch,"shots":64,"complete_reordered_transcript_equal":true,"colored_outputs_bits_phase_toffolis_and_RNG_equal":true,"scratch_state_multiset_equal":true}));}
 let result=serde_json::json!({"status":"PROTECTED_SIMULATOR_ARBITRARY_INPUT_TRANSCRIPT_CONTROL_PASS","scope":"512 uniformly sampled raw assignments and arbitrary initial phase; tool integration only, no curve failure-rate gate or score","original_Q":dims(&original).0,"colored_Q":dims(&colored).0,"rows":rows});std::fs::write(&a[4],serde_json::to_string_pretty(&result).unwrap()).unwrap();println!("all eight complete physical-RNG transcript controls pass");}
